import java.util.*;

class Solution {
  public int findShortestCycle(int n, int[][] edges) {
    List<Integer>[] g = new ArrayList[n];
    for (int i = 0; i < n; i++) g[i] = new ArrayList<>();
    for (int[] e : edges) {
      g[e[0]].add(e[1]);
      g[e[1]].add(e[0]);
    }
    int ans = Integer.MAX_VALUE;
    for (int s = 0; s < n; s++) {
      int[] d = new int[n], p = new int[n];
      Arrays.fill(d, -1);
      Arrays.fill(p, -1);
      ArrayDeque<Integer> q = new ArrayDeque<>();
      d[s] = 0;
      q.add(s);
      while (!q.isEmpty()) {
        int u = q.remove();
        for (int v : g[u]) {
          if (d[v] < 0) {
            d[v] = d[u] + 1;
            p[v] = u;
            q.add(v);
          } else if (p[u] != v) ans = Math.min(ans, d[u] + d[v] + 1);
        }
      }
    }
    return ans == Integer.MAX_VALUE ? -1 : ans;
  }
}
